class EngineModule24:
    """Implementation of EngineModule24 supporting process(data) and get_status()."""

    def __init__(self):
        self._status = "ready"
        self._last_processed_data = None

    def process(self, data):
        """Processes the input data and updates the internal status."""
        self._last_processed_data = data
        self._status = "processed"
        # Return a dictionary containing the status as expected by the test
        return {"status": "success", "data": data}

    def get_status(self):
        """Returns the current status of the engine module."""
        return self._status
